  5	  "type": "module",
  6	  "description": "Deliberately small order-management API used as the worked project throughout Graph Engineering with AI Agents.",
  7	  "engines": {
  8	    "node": ">=20"
  9	  },
 10	  "scripts": {
 11	    "test": "node --test",
 12	    "test:module": "node --test",
 13	    "lint": "node scripts/lint.js",
 14	    "format": "node scripts/lint.js --fix"
 15	  }
 16	}
 17	// Calls every handler in src/api/routes.js the way the router does, with a
 18	// request object and a callback, and reports whether each one answers.
 19	// The unit tests call service functions directly, so a change to a service's
 20	// signature can pass them while the router can no longer reach it.
 21	// Exits 1 if any route errors or never calls back.
 22	import { routes } from '../src/api/routes.js';
 23	
 24	const TIMEOUT_MS = 1500;
 25	let broken = 0;
 26	
 27	for (const route of routes) {
 28	  const outcome = await new Promise((resolve) => {
 29	    const timer = setTimeout(() => resolve({ ok: false, text: 'NO RESPONSE (callback never called)' }), TIMEOUT_MS);
 30	    try {
 31	      route.handler({ params: { id: '1' } }, (err, data) => {
 32	        clearTimeout(timer);
 33	        if (err) resolve({ ok: false, text: `error: ${err.message}` });
 34	        else resolve({ ok: true, text: JSON.stringify(data).slice(0, 60) });
 35	      });
 36	    } catch (err) {
 37	      clearTimeout(timer);
 38	      resolve({ ok: false, text: `threw: ${err.message}` });
 39	    }
 40	  });
 41	  if (!outcome.ok) broken += 1;
 42	  console.log(`${outcome.ok ? 'ok  ' : 'FAIL'}  ${route.method} ${route.path} -> ${outcome.text}`);
 43	}
 44	
 45	console.log(broken ? `${broken} of ${routes.length} routes broken` : `all ${routes.length} routes respond`);
 46	process.exit(broken ? 1 : 0);
 47	#!/usr/bin/env node
 48	// A dependency-free stand-in for eslint and prettier, so the Chapter 6 hooks
 49	// have something real to run on a machine with no npm install.
 50	// Checks: no tab indentation, no trailing whitespace, file ends in one newline.
 51	import { readdirSync, readFileSync, writeFileSync, statSync } from 'node:fs';
 52	import { join } from 'node:path';
 53	
 54	const fix = process.argv.includes('--fix');
 55	const targets = process.argv.slice(2).filter((a) => !a.startsWith('--'));
 56	
 57	function walk(dir) {
 58	  return readdirSync(dir).flatMap((e) => {
 59	    const p = join(dir, e);
 60	    if (statSync(p).isDirectory()) return walk(p);
 61	    return p.endsWith('.js') ? [p] : [];
 62	  });
 63	}
 64	
 65	const files = targets.length ? targets : [...walk('src'), ...walk('tests')];
 66	let problems = 0;
 67	
 68	for (const f of files) {
 69	  const before = readFileSync(f, 'utf8');
 70	  let after = before.replace(/\t/g, '  ').replace(/[ \t]+$/gm, '');
 71	  if (!after.endsWith('\n')) after += '\n';
 72	  after = after.replace(/\n{3,}$/, '\n');
 73	  if (after !== before) {
 74	    if (fix) writeFileSync(f, after);
 75	    else { console.error(`${f}: formatting`); problems += 1; }
 76	  }
 77	}
 78	
 79	if (problems && !fix) {
 80	  console.error(`${problems} file(s) need formatting. Run: npm run format`);
 81	  process.exit(1);
 82	}
 83	console.log(fix ? `formatted ${files.length} file(s)` : `${files.length} file(s) clean`);
 84	import { query, update } from '../db.js';
 85	
 86	// Callback-style database access. Chapter 5 migrates this to UserRepository.
 87	export function listActiveUsers(callback) {
 88	  query('users', (u) => u.deleted_at === null, callback);
 89	}
 90	
 91	export function findUser(id, callback) {
 92	  query('users', (u) => u.id === id, (err, rows) => {
 93	    if (err) return callback(err);
 94	    callback(null, rows[0] ?? null);
 95	  });
 96	}
 97	
 98	export function softDeleteUser(id, when, callback) {
 99	  update('users', id, { deleted_at: when }, callback);
100	}
101	import { query } from '../db.js';
102	
103	// Callback-style database access. Chapter 5 migrates this to OrderRepository.
104	export function listOrdersForUser(userId, callback) {
105	  query('orders', (o) => o.user_id === userId && o.deleted_at === null, callback);
106	}
107	
108	export function totalPaidCents(callback) {
109	  query('orders', (o) => o.status === 'paid' && o.deleted_at === null, (err, rows) => {
110	    if (err) return callback(err);
111	    callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
112	  });
113	}
114	import { query } from '../db.js';
115	
116	// Callback-style database access. Chapter 5 migrates this to a PaymentRepository
117	// the reader adds, which is the part of the exercise with no worked answer.
118	export function findPaymentsForOrder(orderId, callback) {
119	  query('payments', (p) => p.order_id === orderId, callback);
120	}
121	
122	export function uncapturedTotalCents(callback) {
123	  query('payments', (p) => p.captured === false, (err, rows) => {
124	    if (err) return callback(err);
125	    callback(null, rows.reduce((sum, p) => sum + p.amount_cents, 0));
126	  });
127	}
128	// A deliberately tiny in-memory database with a callback API.
129	// The callback style is the point: Chapter 5 migrates the service layer off it.
130	
131	const tables = {
132	  users: [
133	    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
134	    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
135	    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
136	  ],
137	  orders: [
138	    { id: 10, user_id: 1, total_cents: 4200, status: 'paid', deleted_at: null },
139	    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
140	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
141	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
142	  ],
143	  payments: [
144	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
145	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
146	  ],
147	};
148	
149	export function reset() {
150	  tables.users[2].deleted_at = '2026-01-04';
151	  tables.orders.forEach((o) => { o.deleted_at = null; });
152	}
153	
154	// Old-style callback query. Accepts a table name and a predicate.
155	export function query(table, predicate, callback) {
156	  setImmediate(() => {
157	    const rows = tables[table];
158	    if (!rows) return callback(new Error(`no such table: ${table}`));
159	    try {
160	      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
161	    } catch (err) {
162	      callback(err);
163	    }
164	  });
165	}
166	
167	export function update(table, id, patch, callback) {
168	  setImmediate(() => {
169	    const row = (tables[table] || []).find((r) => r.id === id);
170	    if (!row) return callback(new Error(`no row ${id} in ${table}`));
171	    Object.assign(row, patch);
172	    callback(null, { ...row });
173	  });
174	}

